select carrier, case when year(delivered_date) < 2024 then 'before_2024' when year(delivered_date) = 2024 then '2024' else 'after_2024' end as delivered_cohort, round(avg(cost), 2) as avg_cost, max(cost) as max_cost from shipments group by carrier, case when year(delivered_date) < 2024 then 'before_2024' when year(delivered_date) = 2024 then '2024' else 'after_2024' end order by 4 asc, delivered_cohort asc, carrier asc limit 1;
